    "click": "टैब दबाने से केवल दृश्य बदलता है। 6 से 35 गानों वाला कोई भी एल्बम, जिसमें सभी गाने ऑडियो फॉर्मेट में हों, aimusiclist.com पर सेव करते ही या आपके द्वारा चुने गए समय पर सार्वजनिक हो जाता है।",
