    "care": "एक बिल्कुल नई वेबसाइट पर शुरुआत में दिखाने के लिए बहुत कम सामग्री होती है। तस्वीरें दिनों बीतने के साथ-साथ जुड़ती जाती हैं।",
    "like": "यह एक बड़े बाजार से मिलने वाली साप्ताहिक रिपोर्ट की तरह है जिसमें बताया जाता है कि आपके रिकॉर्ड वहां प्रदर्शित होने पर कैसे बिकते हैं।"
