    "what": "एक छोटा कार्ड जो आपके दो प्रशासनिक स्थानों के बारे में बताता है: इस साइट का प्रशासनिक पृष्ठ और आपका meshmelo खाता। प्रत्येक का पता और उसका उपयोग दर्शाया गया है।",
