    "care": "आगंतुकों को प्ले काउंट तभी दिखाई देंगे जब आप साइट जानकारी में **Show play counts to visitors** चालू करेंगे। यह बॉक्स तभी दिखाई देगा जब आपकी साइट प्ले काउंट करती है। आप स्वयं यहां संख्याएं देख सकते हैं।",
    "like": "जैसे कि यह चुनना कि आपकी दुकान में किन रिकॉर्ड्स पर \"120 बार बेचा गया\" का छोटा सा स्टिकर लगाया जाएगा।"
