    "click": "यह पहले आपसे पूछता है, फिर गाना तुरंत सेव हो जाता है। जिन गानों का नाम पहले से यही है, उनका नाम वही रहता है। सिर्फ नए गाने सेव करने का विकल्प गायब हो जाता है।",
