    "when": "जब आप शुरुआत करें तो इसे एक बार भरें। जब आप अपनी साइट का नाम बदलना चाहें या उसके परिचय का तरीका बदलना चाहें तो वापस आएं।",
    "click": "टाइप करते समय कुछ भी सेव नहीं होता है। कार्ड के नीचे स्थित [[साइट की जानकारी सहेजें]] बटन को दबाकर एक साथ सब कुछ सेव करें। आपकी साइट तुरंत बदल जाएगी, और aimusiclist.com को कुछ ही समय बाद नया नाम और विवरण मिल जाएगा।",
    "care": "इस टैब पर मौजूद अन्य कार्ड (SNS, प्ले काउंट, लाइक, इमेज...) अपने आप सेव हो जाते हैं। केवल इसी कार्ड को सेव करने की आवश्यकता है। यदि आप सेव बटन दबाए बिना टैब बंद कर देते हैं, तो आपका टाइप किया हुआ डेटा नष्ट हो जाएगा।",
