    "care": "आप किसी प्रसिद्ध गायक या समूह का नाम, या उससे मिलता-जुलता नाम इस्तेमाल नहीं कर सकते। अगर नाम हमारे किसी परिचित नाम से मिलता-जुलता है, तो उसे सेव करना प्रतिबंधित कर दिया जाएगा। अगर गलती से ऐसा कोई नाम बच जाता है और हमें पता चल जाता है, तो आपकी वेबसाइट aimusiclist द्वारा बंद की जा सकती है।",
