    "care": "अधिकतम 40 अक्षर। आप किसी प्रसिद्ध गायक या समूह का नाम या उससे मिलता-जुलता नाम इस्तेमाल नहीं कर सकते। यदि आप साइट का नाम बदलते हैं और इस बॉक्स में पुराना नाम ही रहता है, तो यह नाम भी बदल जाएगा।",
    "like": "दुकान के बोर्ड पर दुकान का नाम लिखा है। यह दुकान के अंदर काम करने वाले संगीतकार का नेम टैग है।"
