    "what": "आपकी तस्वीर या लोगो, 400×400 आकार में, एक वृत्त के रूप में प्रदर्शित होगा। aimusiclist.com इसे \"नए कलाकार\" अनुभाग में और आपकी वेबसाइट के बगल में भी प्रदर्शित करेगा।",
    "when": "एक स्पष्ट चेहरा या लोगो लगाएं जिसे लोग छोटा होने पर भी पहचान सकें।",
