    "care": "वृत्त द्वारा कोने काट दिए गए हैं, इसलिए महत्वपूर्ण भाग को मध्य में रखें। इसे 100 केबी तक की हल्की तस्वीर के रूप में सहेजा जाता है।",
    "like": "यह दुकान के मालिक की तस्वीर है जो दुकान के बिजनेस कार्ड पर लगी है, जिसे बड़े बाजार में भी बांटा जाता है।"
