    "click": "बॉक्स भरें, [[मेरी साइट पर विज्ञापन दिखाएँ ]] पर टिक करें और [[AdSense सहेजें ]] दबाएँ। इस एडमिन पेज पर विज्ञापन कभी नहीं दिखेंगे, केवल आपकी साइट पर दिखेंगे।",
