    "care": "विज्ञापन सहेजने के बाद भी कुछ समय के लिए खाली रह सकते हैं। यह Google का निर्णय है, आपकी साइट का नहीं। यदि विज्ञापन दिखाई नहीं देते हैं, तो अपना AdSense खाता जांचें।",
